@'
from pathlib import Path
import json,hashlib,numpy as np,pandas as pd
r=Path('experiments/compositional/jutul').resolve()
p=np.load(r/'topology/paths.npz')['I12-W__P16']
idx=np.fromfile(r/'runs/baseline_tuned/cell_map.bin',dtype=np.int64)-1
xyz=np.fromfile(r/'runs/baseline_tuned/centroids.bin').reshape((3,-1),order='F')
sw={k:np.fromfile(r/d/'ImmiscibleSaturation.bin') for k,d in [('round4','diagnostics_round4_1439'),('round5','diagnostics_round5_1439')]}
diffs=[]
for f in (r/'candidates/round4_connectivity').iterdir():
 if f.suffix.lower() in {'.data','.inc'} and hashlib.sha256(f.read_bytes()).digest()!=hashlib.sha256((r/'candidates/round5_path_storage'/f.name).read_bytes()).digest():diffs.append(f.name)
assert diffs==['PORO.inc'],diffs
rows=[]
for cell in p:
 a=int(idx[cell]);rows.append({'I':a%47+1,'J':a//47%39+1,'K':a//(47*39)+1,'depth_m':float(xyz[2,cell]),**{k+'_Sw':float(v[cell]) for k,v in sw.items()}})
ends={}
for k,d in [('round4','diagnostics_round4_1439'),('round5','diagnostics_round5_1439')]:
 m=pd.read_csv(r/d/'matched_oil_water_partial.csv')
 a=m[m.primary & (m.well=='P16')].iloc[-1]
 ends[k]={'simulated_days':float(a.end_days),'p16_observed_water_m3_day':float(a.qw_obs),'p16_simulated_water_m3_day':float(a.qw_sim)}
record={'partial_window_only':True,'cutoff_days':1439,'changed_input_files':diffs,'comparison_purpose':'Hold all permeabilities and initial compositions fixed. Reduce only hydrocarbon-bearing pore volume along the path. Spatial Sw and wellhead water rates are simulation outputs for the indicated windows. The static path alone cannot uniquely identify the source of produced water.','wellhead_response':ends,'path_node_sw':rows}
(r/'results/round5_path_storage_window_diagnostics.json').write_text(json.dumps(record,ensure_ascii=False,indent=2),encoding='utf-8')
print(json.dumps({'changed_files':diffs,'wellhead_response':ends,'path_endpoint_sw':rows[-1]},ensure_ascii=False,indent=2))
s=r/'experiment_status.json';d=json.loads(s.read_text(encoding='utf-8'));d['round5_day1439_actual_control']='Of all DATA/INC files, only PORO.inc differs. P16 water-rate RMSE in rounds 4 and 5 is 59.729 and 53.104 m3/day, respectively. Other wells show essentially the same response. This covers only a partial window. See results/round5_oil_water_comparison_day1439.json and the path-storage window diagnostics.'
s.write_text(json.dumps(d,ensure_ascii=False,indent=2),encoding='utf-8')
'@ | python -X utf8 -
